require "test_helper"

class TmpStorageDebugTest < ActiveSupport::TestCase
  setup do
    Current.session = sessions(:david)
    @account = accounts("37s")
    @board = boards(:writebook)
    @card = cards(:logo)
  end

  def blob(bytes, name: "f.txt", type: "text/plain")
    ActiveStorage::Blob.create_and_upload!(io: StringIO.new("x" * bytes), filename: name, content_type: type)
  end

  def html(b)
    ActionText::Content.new("<p>embed</p>").append_attachables(b).to_html
  end

  test "debug" do
    image = blob(10, name: "i.txt")
    board = blob(20)
    card = blob(30)
    comment = blob(40)

    @card.image.attach(image)
    @board.update!(public_description: html(board))
    @card.update!(description: html(card))
    @card.comments.create!(body: html(comment), creator: users(:david))
    perform_enqueued_jobs only: StorageUsageJob
    puts "1 account=#{@account.reload.bytes_used} board=#{@board.reload.bytes_used} card=#{@card.reload.bytes_used} image=#{@card.image.blob.byte_size}"

    other = boards(:private)
    @card.move_to(other)
    perform_enqueued_jobs only: StorageUsageJob
    puts "2 account=#{@account.reload.bytes_used} old=#{@board.reload.bytes_used} new=#{other.reload.bytes_used} card=#{@card.reload.bytes_used}"

    @card.destroy
    perform_enqueued_jobs only: StorageUsageJob
    puts "3 account=#{@account.reload.bytes_used} old=#{@board.reload.bytes_used} new=#{other.reload.bytes_used}"

    @board.destroy
    perform_enqueued_jobs only: StorageUsageJob
    puts "4 account=#{@account.reload.bytes_used}"
  end
end
EOF
